func (v RulesValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var parameters basetypes.ObjectValue

	if v.Parameters.IsNull() {
		parameters = types.ObjectNull(
			ParametersValue{}.AttributeTypes(ctx),
		)
	}

	if v.Parameters.IsUnknown() {
		parameters = types.ObjectUnknown(
			ParametersValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Parameters.IsNull() && !v.Parameters.IsUnknown() {
		parameters = types.ObjectValueMust(
			ParametersValue{}.AttributeTypes(ctx),
			v.Parameters.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"description": basetypes.StringType{},
		"enabled":     basetypes.BoolType{},
		"name":        basetypes.StringType{},
		"order":       basetypes.Int64Type{},
		"parameters": basetypes.ObjectType{
			AttrTypes: ParametersValue{}.AttributeTypes(ctx),
		},
		"source_field": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"description":  v.Description,
			"enabled":      v.Enabled,
			"name":         v.Name,
			"order":        v.Order,
			"parameters":   parameters,
			"source_field": v.SourceField,
		})

	return objVal, diags
}

func (v RulesValue) Equal(o attr.Value) bool {
	other, ok := o.(RulesValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Enabled.Equal(other.Enabled) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.Order.Equal(other.Order) {
		return false
	}

	if !v.Parameters.Equal(other.Parameters) {
		return false
	}

	if !v.SourceField.Equal(other.SourceField) {
		return false
	}

	return true
}

