func (v ParametersValue) Equal(o attr.Value) bool {
	other, ok := o.(ParametersValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AllowParameters.Equal(other.AllowParameters) {
		return false
	}

	if !v.BlockParameters.Equal(other.BlockParameters) {
		return false
	}

	if !v.ExtractParameters.Equal(other.ExtractParameters) {
		return false
	}

	if !v.ExtractTimestampParameters.Equal(other.ExtractTimestampParameters) {
		return false
	}

	if !v.JsonExtractParameters.Equal(other.JsonExtractParameters) {
		return false
	}

	if !v.JsonParseParameters.Equal(other.JsonParseParameters) {
		return false
	}

	if !v.JsonStringifyParameters.Equal(other.JsonStringifyParameters) {
		return false
	}

	if !v.ParseParameters.Equal(other.ParseParameters) {
		return false
	}

	if !v.RemoveFieldsParameters.Equal(other.RemoveFieldsParameters) {
		return false
	}

	if !v.ReplaceParameters.Equal(other.ReplaceParameters) {
		return false
	}

	return true
}

